Evidence: {"sentence_id":0,"text":"London Electric Vehicle Company Ltd., formerly The London Taxi Corporation Ltd trading as The London Taxi Company; formerly part of Manganese Bronze Holdings plc is an automotive engineering company headquartered in Coventry, United Kingdom, and a wholly owned subsidiary of Chinese automaker Geely.","title":"The London Taxi Company"}
