Evidence: {"sentence_id":0,"text":"Juvénal Rugambarara is a former mayor of Bicumi in the now-defunct Kigali Rural province (Bicumbi now resides mostly in Rwamagana).","title":"Juvénal Rugambarara"}
Evidence: {"sentence_id":1,"text":" He succeeded Laurent Semanza as mayor of the commune on 16 September 1993.","title":"Juvénal Rugambarara"}
