Evidence: {"sentence_id":6,"text":" He will serve his sentence in France.","title":"Juvénal Rugambarara"}
Evidence: {"sentence_id":0,"text":"Boggo Road Gaol (alternative and older spelling \"Bogga\") was a notorious and heritage-listed, Australian prison located on Annerley Road in Dutton Park, an inner southern suburb of Brisbane, Queensland, Australia.","title":"Boggo Road Gaol"}
