Evidence: {"sentence_id":0,"text":"H. Sawin Millett Jr. (born October 8, 1937) is a Maine politician.","title":"Sawin Millett"}
Evidence: {"sentence_id":1,"text":" A Republican, Millett served as the Commissioner of Administrative and Financial Services in the administration of Governor Paul LePage from 2011 to 2014.","title":"Sawin Millett"}
